"""Recognize the existing complete wire-reader program and share exact copies.

Scalar/vector arguments retain their socket types, literals and field contexts.
Every matching output is traced against the existing qualified wire builder;
unmatched outputs/consumers remain intact. No connectivity threshold, sorting,
station arithmetic or original edge is changed. The station-query field stays
in its caller, as in the established shared=True boundary reader.
"""
import bpy

from . import boundary_quad_bridge_nodes as bridge
from . import shared_mesh_guard_nodes as guards
from .field_compaction import constant

PROPERTIES = dict(guards.PROPERTIES, **{
    'ShaderNodeMath': ('operation', 'use_clamp'),
    'ShaderNodeCombineXYZ': (),
    'GeometryNodeInputNamedAttribute': ('data_type',),
    'GeometryNodeStoreNamedAttribute': ('data_type', 'domain'),
    'GeometryNodeSortElements': ('domain',),
    'GeometryNodeSetPosition': (),
    'GeometryNodeInputMeshVertexNeighbors': (),
    'GeometryNodeMeshToPoints': ('mode',),
    'GeometryNodePointsToCurves': (),
})


class WirePattern:
    def __init__(self):
        self.tree = bridge._wire_group()
        self.incoming = {l.to_socket: l.from_socket for l in self.tree.links}
        out = next(n for n in self.tree.nodes if n.type == 'GROUP_OUTPUT')
        self.outputs = {s.name: self.incoming[s] for s in out.inputs if s in self.incoming}
        for n in self.tree.nodes:
            if n.type not in ('GROUP_INPUT', 'GROUP_OUTPUT') and n.bl_idname not in PROPERTIES:
                raise ValueError(('Wire builder changed; review node properties', n.bl_idname))

    def match(self, key, actual, incoming, *, bindings=None, nodes=None):
        values = dict(bindings or {}); mapping = dict(nodes or {}); visited = set()

        def argument(pattern, socket, value=None, kind=None):
            # Do not move implicit scalar/integer conversions across a group
            # interface. Current wire arguments already have their exact types.
            if (socket.type if socket is not None else kind) != pattern.type:
                return False
            binding = ('socket', socket) if socket is not None else ('literal', constant(value), value)
            previous = values.get(pattern.name)
            if previous is not None and previous[:2] != binding[:2]: return False
            values[pattern.name] = binding; return True

        def pair(pattern, actual):
            if pattern.node.type == 'GROUP_INPUT': return argument(pattern, actual)
            a, b = pattern.node, actual.node
            if (a.bl_idname != b.bl_idname or b.mute or pattern.identifier != actual.identifier
                    or a.bl_idname not in PROPERTIES): return False
            if a in mapping and mapping[a] != b: return False
            if any(getattr(a, p) != getattr(b, p) for p in PROPERTIES[a.bl_idname]): return False
            if len(a.inputs) != len(b.inputs): return False
            if (pattern, actual) in visited: return True
            visited.add((pattern, actual)); mapping[a] = b
            for x, y in zip(a.inputs, b.inputs):
                if x.identifier != y.identifier or x.bl_idname != y.bl_idname: return False
                upstream = self.incoming.get(x); links = incoming.get(y, ())
                if upstream is None:
                    if links or constant(getattr(x, 'default_value', None)) != constant(getattr(y, 'default_value', None)):
                        return False
                elif links:
                    if len(links) != 1 or not pair(upstream, links[0].from_socket): return False
                elif upstream.node.type == 'GROUP_INPUT':
                    if not argument(upstream, None, getattr(y, 'default_value', None), y.type): return False
                else: return False
            return True

        return (values, mapping) if pair(self.outputs[key], actual) else None


def factor(roots, *, apply=False):
    groups = guards.reachable(roots); pattern = WirePattern(); rows = []
    anchor = pattern.outputs['Geometry']
